<?php
require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../includes/session.php'; require_once __DIR__.'/../includes/auth.php';
require_login(); require_module_access($conn,'hr_staff','view');
$canCreate=can_module_action($conn,'hr_staff','create');$canEdit=can_module_action($conn,'hr_staff','edit');$csrf=csrf_token();$error='';$message='';
$types=['Resignation','End of Contract','Termination','Retirement','Redundancy','Death','Other'];$statuses=['In Progress','Completed','Cancelled'];
$checks=['handover_completed'=>'Handover completed','assets_returned'=>'Company assets returned','access_revoked'=>'System access revoked','finance_clearance'=>'Finance clearance completed','exit_interview'=>'Exit interview completed'];
$validDate=static function(string $v):bool{if($v==='')return true;$d=DateTime::createFromFormat('!Y-m-d',$v);return $d instanceof DateTime&&$d->format('Y-m-d')===$v;};
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['id']??0);
 if(!verify_csrf_token($_POST['csrf_token']??null))$error='Your security token expired. Refresh and try again.';
 elseif(($id>0&&!$canEdit)||($id===0&&!$canCreate)){http_response_code(403);exit('Forbidden: HR separation permission required.');}
 else{
  $staffId=(int)($_POST['staff_id']??0);$type=(string)($_POST['separation_type']??'Resignation');$notice=trim((string)($_POST['notice_date']??''));$last=trim((string)($_POST['last_working_date']??''));$reason=trim((string)($_POST['reason']??''));$status=(string)($_POST['status']??'In Progress');$notes=trim((string)($_POST['notes']??''));$flags=[];foreach($checks as $key=>$label)$flags[$key]=isset($_POST[$key])?1:0;
  if($staffId<1||!in_array($type,$types,true)||!in_array($status,$statuses,true)||$last===''||!$validDate($last)||!$validDate($notice)||($notice!==''&&$notice>$last))$error='Select a staff member, separation type and valid dates. Notice date cannot be after the last working date.';
  elseif(strlen($reason)>500||strlen($notes)>1500)$error='Reason or notes exceed the allowed length.';
  elseif($status==='Completed'&&array_sum($flags)!==count($checks))$error='An offboarding case cannot be completed until all five clearance checks are confirmed.';
  else{
   $conn->begin_transaction();
   try{
    $lock=$conn->prepare('SELECT id,status FROM hr_staff WHERE id=? FOR UPDATE');if(!$lock)throw new RuntimeException('staff lock prepare failed');$lock->bind_param('i',$staffId);$lock->execute();$staffRow=$lock->get_result()->fetch_assoc();$lock->close();if(!$staffRow)throw new InvalidArgumentException('Selected staff record was not found.');
    if($id>0){$old=$conn->prepare('SELECT status FROM hr_staff_separations WHERE id=? FOR UPDATE');if(!$old)throw new RuntimeException('case lock prepare failed');$old->bind_param('i',$id);$old->execute();$oldRow=$old->get_result()->fetch_assoc();$old->close();if(!$oldRow)throw new InvalidArgumentException('Offboarding case was not found.');if($oldRow['status']==='Completed'&&$status!=='Completed')throw new InvalidArgumentException('A completed offboarding case cannot be reopened or cancelled. Contact an administrator for correction.');}
    $noticeValue=$notice!==''?$notice:null;$reasonValue=$reason!==''?$reason:null;$notesValue=$notes!==''?$notes:null;$actor=(int)($_SESSION['user_id']??0);
    if($id>0){$sql='UPDATE hr_staff_separations SET staff_id=?,separation_type=?,notice_date=?,last_working_date=?,reason=?,status=?,handover_completed=?,assets_returned=?,access_revoked=?,finance_clearance=?,exit_interview=?,notes=?,updated_by=?,completed_at=CASE WHEN ?="Completed" THEN COALESCE(completed_at,NOW()) ELSE NULL END WHERE id=?';$st=$conn->prepare($sql);if(!$st)throw new RuntimeException('case update prepare failed');$st->bind_param('isssssiiiiisisi',$staffId,$type,$noticeValue,$last,$reasonValue,$status,$flags['handover_completed'],$flags['assets_returned'],$flags['access_revoked'],$flags['finance_clearance'],$flags['exit_interview'],$notesValue,$actor,$status,$id);$st->execute();$st->close();$caseId=$id;}
    else{$sql='INSERT INTO hr_staff_separations (staff_id,separation_type,notice_date,last_working_date,reason,status,handover_completed,assets_returned,access_revoked,finance_clearance,exit_interview,notes,created_by,updated_by,completed_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,IF(?="Completed",NOW(),NULL))';$st=$conn->prepare($sql);if(!$st)throw new RuntimeException('case insert prepare failed');$st->bind_param('isssssiiiiisiis',$staffId,$type,$noticeValue,$last,$reasonValue,$status,$flags['handover_completed'],$flags['assets_returned'],$flags['access_revoked'],$flags['finance_clearance'],$flags['exit_interview'],$notesValue,$actor,$actor,$status);$st->execute();$caseId=(int)$conn->insert_id;$st->close();}
    if($status==='Completed'){$up=$conn->prepare("UPDATE hr_staff SET status='Separated',updated_by=? WHERE id=?");if(!$up)throw new RuntimeException('staff status update prepare failed');$up->bind_param('ii',$actor,$staffId);$up->execute();$up->close();}
    if(function_exists('audit'))audit('hr_separation_saved','case_id='.$caseId.',staff_id='.$staffId.',status='.$status);
    $conn->commit();$message=$status==='Completed'?'Offboarding completed; staff status changed to Separated.':'Offboarding case saved.';
   }catch(Throwable $ex){$conn->rollback();if($ex instanceof InvalidArgumentException)$error=$ex->getMessage();else{error_log('HR offboarding save failed: '.$ex->getMessage());$error='Offboarding could not be saved. Review the record and try again.';}}
  }
 }
}
$edit=null;$editId=(int)($_GET['edit']??0);if($editId>0&&$canEdit){$st=$conn->prepare('SELECT * FROM hr_staff_separations WHERE id=? LIMIT 1');if($st){$st->bind_param('i',$editId);$st->execute();$edit=$st->get_result()->fetch_assoc();$st->close();}}
$staff=$conn->query("SELECT id,staff_no,first_name,last_name,department FROM hr_staff WHERE status <> 'Separated' ORDER BY department,last_name");
$rows=$conn->query('SELECT x.*,s.staff_no,s.first_name,s.last_name,s.department FROM hr_staff_separations x JOIN hr_staff s ON s.id=x.staff_id ORDER BY FIELD(x.status,\'In Progress\',\'Completed\',\'Cancelled\'),x.last_working_date DESC');
$summary=$conn->query("SELECT COUNT(*) total,SUM(status='In Progress') pending,SUM(status='Completed') completed FROM hr_staff_separations");$counts=$summary?$summary->fetch_assoc():['total'=>0,'pending'=>0,'completed'=>0];
$e=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/sidebar.php';
?>
