<div class="hro-field"><label>Separation type</label><select name="separation_type"><?php foreach($types as $t):?><option value="<?= $e($t) ?>" <?= (($edit['separation_type']??'Resignation')===$t)?'selected':'' ?>><?= $e($t) ?></option><?php endforeach;?></select></div><div class="hro-field"><label>Case status</label><select name="status"><?php foreach($statuses as $st):?><option value="<?= $e($st) ?>" <?= (($edit['status']??'In Progress')===$st)?'selected':'' ?>><?= $e($st) ?></option><?php endforeach;?></select></div>
<div class="hro-field"><label>Notice date</label><input type="date" name="notice_date" value="<?= $e($edit['notice_date']??'') ?>"></div><div class="hro-field"><label>Last working date *</label><input type="date" name="last_working_date" required value="<?= $e($edit['last_working_date']??'') ?>"></div><div class="hro-field"><label>Reason</label><input name="reason" maxlength="500" value="<?= $e($edit['reason']??'') ?>"></div>
<div class="hro-wide"><div class="hro-head" style="padding:0 0 10px;border:0">Clearance checklist · all five required to complete</div><div class="hro-checks"><?php foreach($checks as $key=>$label):?><label class="hro-check"><input type="checkbox" name="<?= $e($key) ?>" value="1" <?= !empty($edit[$key])?'checked':'' ?>><?= $e($label) ?></label><?php endforeach;?></div></div>
