<section class="hro-card"><div class="hro-head">Separation register</div><div class="hro-tablewrap"><table class="hro-table"><thead><tr><th>Staff member</th><th>Type / reason</th><th>Last working date</th><th>Clearance</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):$done=(int)$r['handover_completed']+(int)$r['assets_returned']+(int)$r['access_revoked']+(int)$r['finance_clearance']+(int)$r['exit_interview'];?><tr><td><span class="hro-name"><?= $e($r['first_name'].' '.$r['last_name']) ?></span><span class="hro-sub"><?= $e($r['staff_no'].' · '.$r['department']) ?></span></td><td><?= $e($r['separation_type']) ?><span class="hro-sub"><?= $e($r['reason']?:'No reason recorded') ?></span></td><td><?= $e($r['last_working_date']) ?></td><td><span class="hro-pill <?= $done===5?'hro-done':'hro-pending' ?>"><?= $done ?>/5 checks</span></td><td><?= $e($r['status']) ?></td><td><?php if($canEdit&&$r['status']!=='Completed'):?><a class="hro-btn hro-muted" href="?edit=<?= (int)$r['id'] ?>"><i class="fas fa-pen"></i> Update</a><?php else:?>—<?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="6" style="text-align:center;padding:32px;color:#77869a">No separation cases have been recorded.</td></tr><?php endif;?></tbody></table></div></section></div></div>
